script:
frappe.listview_settings["ZKtecho Check-In Logs"] = {
	onload: function (listview) {
		listview.page.add_inner_button(__("Sync ZKTeco Logs"), function () {
			frappe.confirm(
				__("Do you want to sync ZKTeco logs now?"),
				function () {
					frappe.call({
						method: "petroka_custom.petroka_custom.custom_script.zkteco.enqueue_sync_zkteco_logs",
						freeze: true,
						freeze_message: __("Scheduling ZKTeco sync..."),
						callback: function (r) {
							if (!r.exc) {
								frappe.show_alert({
									message: __("ZKTeco sync has been scheduled successfully."),
									indicator: "green"
								}, 5);

								listview.refresh();
							}
						},
						error: function () {
							frappe.msgprint({
								title: __("Error"),
								message: __("ZKTeco sync could not be scheduled. Please check Error Log."),
								indicator: "red"
							});
						}
					});
				}
			);
		});
	}
};
